def build_nouns_science_tech(existing_norms: set[str]):
    entries = []
    seen = set()
    rank = 1

    for row in SCIENCE_ITEMS:
        headword = row[1]
        norm = norm_vocab(headword)
        if norm in existing_norms or norm in seen:
            continue
        seen.add(norm)

        gender = row[2]
        level = row[3]
        msa = row[4]
        eg = row[5]
        domain = row[6]

        art = "El" if gender == "m" else "La"
        ex_es = f"{art} {headword} es un concepto clave en el desarrollo científico y tecnológico."
        ex_ar = f"الـ{msa} مفهوم أساسي في التطور العلمي والتقني."

        entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        entries.append(entry)
        rank += 1

    emit_bundle(
        filename="vocab-cv-nouns-science-tech.json",
        bundle_slug="cv-nouns-science-tech",
        title_ar="معجم العلوم والتقنية والهندسة والفيزياء والكيمياء والفلك",
        entries=entries
    )
    return len(entries), seen

if __name__ == "__main__":
    count, _ = build_nouns_science_tech(get_existing_norms())
    print(f"Generated {count} entries in vocab-cv-nouns-science-tech.json")
